INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Kunci Biasa Mudah Dibobol, Pintu Kos Perlu Perlindungan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Gembok dan kunci biasa punya kelemahan: anak kunci bisa diduplikat, digergaji, atau dibuka paksa. Untuk ruangan kos, gudang kecil, atau kotak penyimpanan, kunci kombinasi elektronik adalah solusi murah dan aman. Kabar baiknya, kamu bisa membuatnya sendiri dengan Arduino Uno dan keypad — total biaya di bawah seratus ribu rupiah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Cara Kerja Kunci Kombinasi Arduino$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Prinsipnya sederhana: keypad 4x4 menjadi alat input kode PIN. Arduino membandingkan PIN yang diketik dengan kode yang tersimpan di memori. Jika cocok, Arduino menggerakkan motor servo untuk membuka kait (misalnya servo memutar 90 derajat menarik palang pintu). Jika salah tiga kali berturut-turut, sistem bisa dikunci sementara dan membunyikan buzzer sebagai alarm.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$$Arduino Uno (atau Nano) beserta kabel USB$$, $$Keypad matriks 4x4 + library Keypad.h$$, $$Motor servo SG90 + bracket kait pintu$$, $$LCD 16x2 dengan modul I2C (opsional, untuk tampilan status)$$, $$Buzzer aktif 5V (untuk alarm kode salah)$$, $$Breadboard, kabel jumper, dan catu daya 5V (power bank atau adaptor)$$, $$Laptop dengan Arduino IDE dan library Servo, Keypad, LiquidCrystal_I2C$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Membuat Kunci Kombinasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$$Rangkai keypad 4x4 ke pin digital 2-9 Arduino (4 baris + 4 kolom).$$, $$Hubungkan servo ke pin 10 (kabel kuning/oranye = sinyal, merah = 5V, cokelat = GND).$$, $$Pasang buzzer ke pin 11 dan LCD I2C ke pin A4 (SDA) dan A5 (SCL).$$, $$Install library Keypad, Servo, dan LiquidCrystal_I2C melalui Library Manager Arduino IDE.$$, $$Tulis program: baca tombol keypad, kumpulkan 4 digit, bandingkan dengan kode rahasia (misalnya 1234), gerakkan servo jika benar.$$, $$Tambahkan fitur keamanan: setelah 3 kali salah, bunyikan buzzer dan kunci input selama 30 detik.$$, $$Upload program, lalu uji dengan kode benar dan kode salah.$$, $$Pasang servo ke kait pintu/kotak dan rapikan semua kabel agar tidak terlepas.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Keselamatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$Jangan pakai untuk pintu utama rumah — sistem DIY bukan pengganti kunci standar keamanan tinggi.$$, $$Ganti kode default segera; kode 1234 mudah ditebak orang.$$, $$Pastikan catu daya stabil — Arduino yang kehabisan daya membuat kunci terkunci atau terbuka tergantung desain kait.$$, $$Servo SG90 kecil; jangan paksa memutar kait yang macet karena bisa merusak gear plastiknya.$$, $$Jangan biarkan kabel listrik 220V berdekatan dengan rangkaian 5V ini.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Periksa: ketik kode benar — servo harus bergerak membuka kait dan LCD menampilkan 'AKSES DITERIMA'. Ketik kode salah 3 kali — buzzer harus berbunyi dan input terkunci 30 detik. Simulasikan mati listrik dan pastikan kamu punya cara darurat membuka (lubang kunci cadangan). Tindak lanjut: tambahkan sensor PIR untuk alarm gerakan, simpan kode di EEPROM agar tidak hilang saat reset, dan catat kode rahasia di tempat aman yang hanya kamu tahu.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Bakwan Jagung Lembek dan Berminyak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bakwan jagung sering mengecewakan: luarnya lembek, dalamnya basah, dan minyaknya menetes-netes. Padahal bakwan jagung yang enak harus renyah di luar, lembut gurih di dalam, dan tidak menyerap minyak berlebihan. Masalahnya bukan pada resepnya, tapi pada tekniknya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Kunci Kerenyahan Bakwan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Kerenyahan bakwan ditentukan tiga hal: komposisi tepung, suhu minyak, dan kadar air adonan. Tepung beras memberi kerenyahan, tepung terigu memberi struktur. Minyak yang cukup panas (sekitar 170 derajat Celsius) langsung membentuk kerak luar sehingga minyak tidak meresap ke dalam. Adonan yang terlalu encer membuat bakwan lembek; terlalu kental membuat bakwan keras.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Bahan-bahan (untuk sekitar 15 buah)$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, to_jsonb(ARRAY[$$3 buah jagung manis, pipil (pilih yang tua agar manis dan tidak berair)$$, $$100 gram tepung terigu protein sedang$$, $$50 gram tepung beras$$, $$1 butir telur$$, $$3 siung bawang putih, haluskan$$, $$1 batang daun bawang, iris tipis$$, $$1 sendok teh garam, 1/2 sendok teh merica, 1/2 sendok teh ketumbar bubuk$$, $$100-120 ml air es (jangan air hangat)$$, $$Minyak goreng secukupnya untuk menggoreng terendam$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah Membuat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, to_jsonb(ARRAY[$$Pipil jagung, lalu tumbuk kasar setengah bagian jagung agar teksturnya bervariasi.$$, $$Campur tepung terigu, tepung beras, garam, merica, dan ketumbar dalam wadah.$$, $$Masukkan telur dan air es sedikit demi sedikit sambil diaduk hingga adonan kental seperti bubur kental (tidak encer).$$, $$Masukkan jagung pipil, bawang putih halus, dan daun bawang. Aduk rata.$$, $$Panaskan minyak dalam jumlah banyak dengan api sedang hingga benar-benar panas (tes: tetesan adonan langsung mengapung dan mendesis).$$, $$Ambil satu sendok makan adonan, pipihkan sedikit, lalu goreng 3-4 buah per batch agar suhu minyak tidak turun.$$, $$Goreng hingga kuning keemasan sekitar 3-4 menit per sisi, angkat, dan tiriskan dengan posisi berdiri.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$Minyak kurang panas: bakwan menyerap minyak dan lembek. Panaskan dulu dengan benar.$$, $$Adonan terlalu encer: bakwan hancur di minyak. Tambahkan tepung sedikit demi sedikit.$$, $$Menggoreng terlalu banyak sekaligus: suhu minyak turun drastis, bakwan berminyak.$$, $$Air hangat membuat gluten terigu aktif berlebihan — bakwan jadi alot. Pakai air es.$$, $$Minyak bekas yang sudah hitam membuat rasa pahit; ganti jika sudah terlalu gelap.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Periksa: warna kuning keemasan merata; tekstur renyah dengan bunyi 'kres' yang jelas saat digigit; rasa manis gurih jagung terasa; saat ditekan dengan tisu hanya sedikit noda minyak. Agar tetap renyah, jangan tutup dalam wadah tertutup saat masih panas — uapnya membuat bakwan lembek. Sisa adonan bisa disimpan di kulkas maksimal satu hari, aduk lagi sebelum digoreng. Sajikan dengan cabai rawit atau sambal.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Fosfor: Unsur Pembawa Cahaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Fosfor adalah unsur kimia dengan simbol P dan nomor atom 15. Ia terkenal karena salah satu bentuknya — fosfor putih — dapat bersinar kehijauan dalam gelap saat bereaksi dengan oksigen. Nama 'fosfor' berasal dari bahasa Yunani 'phosphoros' yang berarti pembawa cahaya. Fosfor ditemukan pada tahun 1669 oleh Hennig Brand, seorang alkemis Jerman yang sedang mencari batu filsuf dari urine manusia — ia malah menemukan zat yang bersinar. Fosfor adalah nonlogam yang sangat reaktif dan tidak ditemukan bebas di alam, melainkan dalam bentuk senyawa fosfat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Tiga Bentuk Fosfor dan Korek Api$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Fosfor memiliki beberapa bentuk alotropi. Fosfor putih sangat reaktif, beracun, dan bersinar dalam gelap — dipakai untuk peluru penanda dan bom asap, dan harus disimpan di dalam air. Fosfor merah jauh lebih stabil dan aman; inilah yang ada di sisi kotak korek api. Saat digesek, panas gesekan mengubah sedikit fosfor merah menjadi fosfor putih yang langsung terbakar dan menyulut kepala korek. Fosfor hitam adalah bentuk paling stabil dan menghantarkan listrik, mirip grafit pada karbon.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Peran Fosfor bagi Kehidupan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Tanpa fosfor, kehidupan tidak ada. Fosfor adalah penyusun tulang dan gigi dalam bentuk kalsium fosfat, bagian dari DNA dan RNA (tulang punggung rantai fosfat), serta ATP — molekul 'baterai' yang menyimpan dan melepaskan energi di setiap sel tubuh. Tanaman pun membutuhkan fosfor sebagai unsur hara makro dalam pupuk. Berbeda dengan karbon atau nitrogen, fosfor tidak punya fase gas di atmosfer; siklusnya berjalan lambat dari batuan fosfat ke tanah, tumbuhan, hewan, lalu kembali ke tanah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Manfaat Industri dan Bahaya Fosfor$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Sebagian besar fosfor dunia dipakai untuk pupuk. Senyawa fosfor juga dipakai dalam deterjen (kini dibatasi karena mencemari air), pasta gigi, kembang api, bahan tahan api, dan asam fosfat pada minuman bersoda. Namun fosfor putih sangat beracun dan dapat menyebabkan luka bakar kimia yang dalam karena terus terbakar saat terkena udara. Paparan kronisnya pernah menyebabkan penyakit 'rahang fosfor' pada pekerja pabrik korek api abad ke-19, dan penggunaannya sebagai senjata kini dibatasi hukum internasional.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Fosfor dan Masa Depan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Cadangan batuan fosfat dunia terbatas dan terkonsentrasi di sedikit negara, sehingga para ilmuwan mencari cara mendaur ulang fosfor dari limbah dan kotoran. Fakta singkat: simbol P, nomor atom 15, golongan nitrogen; ditemukan 1669; fosfor putih bersinar dalam gelap; penyusun DNA, RNA, ATP, tulang, dan gigi; fosfor merah ada di sisi kotak korek api. Fosfor mengingatkan kita bahwa satu unsur bisa sekaligus menjadi sumber kehidupan, cahaya yang indah, dan bahaya yang mematikan — tergantung bagaimana manusia menggunakannya.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Pemberontakan Andi Azis 1950$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Pada April 1950, Kapten Andi Azis — seorang perwira KNIL asal Sulawesi Selatan — memimpin pemberontakan bersenjata di Makassar. Peristiwa ini menjadi ujian pertama bagi Republik Indonesia Serikat (RIS) yang baru berusia beberapa bulan. Hasil Konferensi Meja Bundar 1949 telah membentuk RIS sebagai federasi 16 negara bagian, termasuk Negara Indonesia Timur (NIT) yang beribu kota di Makassar. Banyak pihak tidak puas dengan bentuk federal yang dianggap warisan Belanda, sementara ribuan bekas tentara KNIL belum jelas nasibnya — apakah masuk APRIS atau dibubarkan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Siapa Andi Azis dan Apa Tuntutannya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Andi Azis adalah perwira KNIL berpangkat kapten yang bertugas di Makassar. Ia khawatir para bekas tentara KNIL asal Indonesia Timur akan disingkirkan dari APRIS, dan menuntut agar pasukan APRIS dari Jawa tidak dikirim ke Makassar. Setelah tuntutannya ditolak pemerintah pusat, pada 5 April 1950 pasukannya menyerang dan menduduki markas APRIS di Makassar, menawan sejumlah perwira termasuk Letkol Ahmad Yunus Mokoginta, serta menguasai instalasi penting kota. Andi Azis lalu mengeluarkan ultimatum — tetapi pemerintah RIS menolak berunding dengan pemberontak bersenjata.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Penumpasan dan Akhir Pemberontakan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pemerintah RIS bergerak cepat: pasukan APRIS di bawah Kolonel Alex Kawilarang dikirim ke Makassar melalui Operasi Kilat, dan dalam hitungan hari perlawanan Andi Azis runtuh. Andi Azis sendiri kemudian ditangkap di Jakarta setelah dipancing datang dengan alasan perundingan, lalu diadili dan dijatuhi hukuman penjara. Pemberontakan berakhir dalam waktu kurang dari sebulan — pesan tegas bahwa pemerintah pusat tidak mentolerir pembangkangan bersenjata.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Dampak bagi Bentuk Negara Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pemberontakan Andi Azis — bersama pemberontakan RMS di Maluku beberapa bulan kemudian — menjadi alasan kuat membubarkan RIS. Pada 17 Agustus 1950, RIS resmi dibubarkan dan Indonesia kembali menjadi negara kesatuan: NKRI. Sejak itu, federalisme dianggap identik dengan warisan kolonial di Indonesia. Peristiwa ini mengajarkan bahwa kemerdekaan tidak otomatis membawa persatuan — persatuan harus terus dirawat lewat dialog, bukan dianggap selesai saat proklamasi dibacakan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Linimasa Singkat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$27 Desember 1949: RIS resmi berdiri sebagai negara federal.$$, $$5 April 1950: Andi Azis menduduki markas APRIS di Makassar.$$, $$April 1950: Operasi Kilat menumpas pemberontakan dalam hitungan hari.$$, $$17 Agustus 1950: RIS dibubarkan, NKRI kembali menjadi negara kesatuan.$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu: (1) menjelaskan pengertian globalisasi menurut para ahli, (2) mengidentifikasi faktor-faktor pendorong globalisasi, (3) menganalisis dampak positif dan negatif globalisasi bagi masyarakat Indonesia, dan (4) memberikan contoh nyata globalisasi dalam kehidupan sehari-hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian dan Faktor Pendorong Globalisasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Globalisasi adalah proses mendunianya berbagai aspek kehidupan — ekonomi, budaya, teknologi, dan komunikasi — sehingga batas antarnegara semakin kabur. Menurut Anthony Giddens, globalisasi adalah intensifikasi hubungan sosial dunia yang menghubungkan peristiwa di satu tempat dengan peristiwa di tempat lain yang jauh; dunia menjadi 'kampung global'. Faktor pendorongnya: kemajuan teknologi komunikasi dan informasi (internet, smartphone, media sosial); kemajuan teknologi transportasi (pesawat, kapal kontainer); perdagangan bebas dan investasi asing; perkembangan ilmu pengetahuan lintas negara; serta kerja sama internasional lewat PBB, ASEAN, dan WTO.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dampak Positif dan Negatif$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Dampak positif: akses informasi dan ilmu pengetahuan menjadi mudah, produk berkualitas tersedia dengan harga bersaing, lapangan kerja bertambah lewat investasi asing, pertukaran budaya memperkaya wawasan, dan teknologi kesehatan serta pendidikan berkembang lewat kolaborasi global. Dampak negatif: budaya lokal tergerus budaya asing (westernisasi), kesenjangan ekonomi melebar, ketergantungan pada produk impor melemahkan industri dalam negeri, gaya hidup konsumtif meningkat, serta masuknya paham radikal dan berita bohong lewat internet.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Globalisasi di Indonesia: Ekonomi dan Budaya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Di bidang ekonomi, globalisasi terlihat dari masuknya perusahaan multinasional, perdagangan bebas ASEAN (MEA), dan mudahnya berbelanja produk luar negeri lewat e-commerce — petani dan UMKM lokal harus bersaing dengan produk impor murah. Di bidang budaya, terlihat dari menjamurnya makanan cepat saji asing, film dan musik Korea atau Hollywood yang digemari remaja, hingga tren fashion global. Namun sebaliknya, batik, rendang, dan gamelan Indonesia justru semakin dikenal dunia — globalisasi juga bisa menjadi panggung bagi budaya lokal.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Sikap Menghadapi Globalisasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Sikap yang tepat bukanlah menolak atau menerima mentah-mentah, melainkan selektif: mengambil yang baik (teknologi, ilmu pengetahuan) dan menyaring yang buruk (gaya hidup merusak, paham ekstrem). Memperkuat identitas nasional dan daya saing adalah benteng terbaik. Contoh nyata di sekitarmu: menonton drama Korea sambil memesan makanannya lewat ojek online; UMKM batik menjual ke luar negeri lewat marketplace global; pelajar mengikuti kelas daring universitas luar negeri; tren TikTok yang sama viral di Jakarta, Seoul, dan New York dalam waktu bersamaan. Singkatnya: globalisasi didorong teknologi informasi, transportasi, dan kerja sama internasional; dampaknya ganda — peluang sekaligus tantangan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$$Soal 1: Jelaskan pengertian globalisasi menurut Anthony Giddens! Kunci: intensifikasi hubungan sosial dunia yang menghubungkan peristiwa lokal dengan peristiwa di tempat yang jauh.$$, $$Soal 2: Sebutkan tiga faktor pendorong globalisasi! Kunci: teknologi komunikasi/informasi, teknologi transportasi, perdagangan bebas/investasi asing (atau kerja sama internasional).$$, $$Soal 3: Berikan satu contoh dampak positif dan satu dampak negatif globalisasi di bidang budaya Indonesia! Kunci: positif — batik dikenal dunia; negatif — budaya lokal tergerus tren asing.$$, $$Penutup: jika kamu bisa menjawab ketiganya dengan benar, berarti kamu sudah memahami materi globalisasi. Pelajari kembali bagian dampak positif-negatif karena sering keluar dalam ujian.$$]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu diharapkan bisa: (1) menjelaskan apa itu pahlawan nasional, (2) menyebutkan pahlawan Indonesia dan perjuangannya, (3) menyebutkan nilai-nilai kepahlawanan yang bisa ditiru dalam kehidupan sehari-hari.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian dan Pahlawan Proklamasi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pahlawan nasional adalah orang yang berjasa besar bagi bangsa dan negara Indonesia, terutama dalam perjuangan kemerdekaan. Gelar Pahlawan Nasional diberikan resmi oleh pemerintah Indonesia kepada mereka yang telah wafat dan terbukti berjuang dengan luar biasa. Pahlawan proklamasi di antaranya: Ir. Soekarno (presiden pertama, pembaca teks Proklamasi 17 Agustus 1945), Drs. Mohammad Hatta (wakil presiden pertama, ikut merumuskan Proklamasi), Sayuti Melik (mengetik naskah Proklamasi), dan Fatmawati (menjahit bendera Merah Putih pertama).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Pahlawan Perang dan Pahlawan Daerah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Setelah merdeka, Indonesia masih berperang melawan Belanda. Jenderal Soedirman memimpin perang gerilya meski sakit keras, dan Bung Tomo membakar semangat arek-arek Surabaya pada 10 November 1945 (Hari Pahlawan). Pahlawan dari berbagai daerah: Pangeran Diponegoro (Jawa Tengah, Perang Jawa 1825-1830), Cut Nyak Dhien (Aceh), Tuanku Imam Bonjol (Sumatera Barat, Perang Padri), Pattimura (Maluku, 1817), R.A. Kartini (Jawa Tengah, emansipasi perempuan), dan Ki Hajar Dewantara (Yogyakarta, bapak pendidikan Indonesia).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Pahlawan Masa Kini dan Cara Menghargainya$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pahlawan tidak hanya ada di masa perang. Dokter yang berjuang saat wabah, guru di daerah terpencil, atlet yang mengharumkan nama Indonesia, dan siapa pun yang berbuat baik untuk orang banyak juga pahlawan. Kamu pun bisa menjadi pahlawan dengan caramu sendiri. Kita menghargai jasa pahlawan dengan: belajar rajin, mengikuti upacara bendera dengan khidmat, menjaga kebersihan lingkungan, tidak menyia-nyiakan kemerdekaan, dan mendoakan para pahlawan yang telah gugur.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Nilai Kepahlawanan yang Bisa Ditiru$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, to_jsonb(ARRAY[$$Berani: berani membela kebenaran dan berani mencoba hal baru.$$, $$Rela berkorban: mendahulukan kepentingan bersama di atas kepentingan sendiri.$$, $$Pantang menyerah: tidak mudah putus asa saat menghadapi kesulitan.$$, $$Cinta tanah air: bangga menjadi anak Indonesia dan menjaga nama baik bangsa.$$, $$Jujur dan disiplin: meneladani sikap para pahlawan dalam kehidupan sehari-hari.$$]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, to_jsonb(ARRAY[$$Soal 1: Siapa yang mengetik naskah Proklamasi Kemerdekaan Indonesia? Kunci: Sayuti Melik.$$, $$Soal 2: Tanggal berapa Hari Pahlawan diperingati dan peristiwa apa yang melatarbelakanginya? Kunci: 10 November, pertempuran Surabaya 1945.$$, $$Soal 3: Sebutkan dua pahlawan dari luar Pulau Jawa beserta daerah asalnya! Kunci: misalnya Cut Nyak Dhien (Aceh) dan Pattimura (Maluku), atau Tuanku Imam Bonjol (Sumatera Barat).$$, $$Penutup: kalau kamu bisa menjawab semuanya dengan benar, hebat! Kemerdekaan yang diperjuangkan para pahlawan dengan nyawa harus kita isi dengan belajar giat dan berbuat baik.$$]));
